const fs = require("fs");
const path = require("path");
const archiver = require("archiver");

function getCurrentDate() {
  const date = new Date();
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}${month}${day}`;
}

function createZip(customExclusions = []) {
  const outputFile = `backup-${getCurrentDate()}.zip`;
  const output = fs.createWriteStream(outputFile);
  const archive = archiver("zip", { zlib: { level: 9 } });

  archive.pipe(output);

  const defaultExclusions = ["node_modules", outputFile];
  const exclusions = [...defaultExclusions, ...customExclusions];

  console.log(`Creating ${outputFile}...`);
  console.log("Excluding:", exclusions);

  archive.directory("./", false, (entry) => {
    const relativePath = entry.name;
    const shouldExclude = exclusions.some((exclusion) =>
      relativePath.startsWith(exclusion)
    );
    return shouldExclude ? false : entry;
  });

  archive.finalize();

  output.on("close", () => {
    console.log(
      `${outputFile} created successfully (${archive.pointer()} bytes)`
    );
  });

  archive.on("error", (err) => {
    console.error("Error creating zip:", err);
    process.exit(1);
  });
}

module.exports = { createZip };
